local cache,order={},{}
function S.WorldDB.JournalQuests(slug)
    if cache[slug] then return cache[slug] end
    local build=builders[slug];if not build then return nil end
    if #order>=2 then cache[table.remove(order,1)]=nil end
    local rows=build();cache[slug]=rows;order[#order+1]=slug
    return rows
end
